unto'=>$r['assunto']??'','_status'=>$r['status']??'Nova'],$cont))),0,15) as $r):?><tr><td>#<?=$r['id']?></td><td><?=e($r['_tipo'])?></td><td><?=e($r['nome']??'')?></td><td><?=e($r['_assunto'])?></td><td><?=e($r['created_at']??'')?></td><td><?=e($r['_status'])?></td></tr><?php endforeach;?></tbody></table></div></div></body></html>
